"use client";

import { useConfigureSuggestions } from "@copilotkit/react-core/v2";

/**
 * Suggestion layers:
 *   1. Static starters — shown on an empty thread; cover the hero
 *      flows so a new user sees the range of capabilities.
 *   2. LLM-generated follow-ups — generated by the dedicated
 *      "suggester" agent (see graph/suggester.py + /api/copilotkit
 *      route). CopilotKit clones that agent after each assistant
 *      turn, forces tool_choice: copilotkitSuggest, and extracts the
 *      suggestions from the tool call. Rules live in the suggester's
 *      system prompt — no frontend heuristics.
 */
export function useSuggestions() {
  useConfigureSuggestions({
    available: "before-first-message",
    suggestions: [
      { title: "Run yesterday's pipeline", message: "Run the pipeline for yesterday's new MQLs" },
      { title: "Fetch yesterday's", message: "Fetch yesterday's contacts from HubSpot" },
      { title: "Recent leads", message: "Show contacts from the last 7 days" },
      { title: "Review drafts", message: "Show drafts pending review" },
      { title: "Check replies", message: "Check for new replies in the last 24 hours" },
      { title: "Pipeline stats", message: "How has the pipeline performed this week?" },
    ],
  });

  useConfigureSuggestions({
    available: "after-first-message",
    minSuggestions: 2,
    maxSuggestions: 3,
    providerAgentId: "suggester",
    consumerAgentId: "default",
    instructions:
      "Read the conversation and generate follow-up suggestions per your system prompt. " +
      "Use real IDs / company names from the conversation. Prefer multi-entity actions " +
      "when several contacts or engagements are in scope.",
  });
}
